// GalaxyServiceServer is the server API for GalaxyService service.
// All implementations must embed UnimplementedGalaxyServiceServer
// for forward compatibility.
//
// GalaxyService 是创作面：用户放下一组具名文件与素材，然后把它发布成一个
// 别人能打开的站点。
//
// 边界：它不回答"你是谁"（认证）也不回答"你能做什么"（RBAC）。**两把闸门
// 各管一件事**：`galaxy.*` 权限码决定这个主体有没有资格创作，工程的拥有者
// 决定他能不能碰这一个工程。后者不由 RBAC 表达，也不在本服务的请求里出现
// ——**接口面上没有"指定拥有者"这个形状**，拥有者由凭证决定。
//
// **"不是你的"与"不存在"返回同一个结论。** 区分它们等于提供一个工程枚举
// 接口：拿着别人的工程标识反复调用，"不存在"与"无权访问"的差集就能把一个
// 不可猜标识试出来。而工程标识是发布地址的一部分，猜出它就能看到别人的
// 页面（见 docs/design/galaxy/project-versioning.md）。
//
// 作用域从**凭证绑定的默认作用域**解析：请求里没有作用域字段，也不该有
// ——工程是资源归属的载体，不是作用域的载体。
type GalaxyServiceServer interface {
	// 读取当前部署下创作能力的边界：能不能传素材、能不能发布、各项上限。
	//
	// 它是**能力下发点**，与档案的 avatar_upload_enabled 同一取向：能力由
	// 服务端说，客户端不猜。前端据此不渲染未启用的入口，而不是渲染一个点了
	// 报错的控件。它退回的每一项都是部署形态的公开事实，不因调用者而异。
	GetCapabilities(context.Context, *GetCapabilitiesRequest) (*GetCapabilitiesResponse, error)
	// 列出调用者自己的工程。**只有这一个列表入口，且它的范围由凭证决定。**
	//
	// 刻意没有"列出所有工程"或"列出某个主体的工程"的形状：工程标识不可猜
	// 是发布态匿名可读的唯一防线，任何枚举入口都会把它降级成"打开就能逛"。
	ListProjects(context.Context, *ListProjectsRequest) (*ListProjectsResponse, error)
	// 创建一个工程，并选一个或多个**内容槽**。标识由服务端分配，不可猜、不可改、
	// 不复用。
	//
	// **至少选一个槽，此后只增不删**（见 AddProjectSlot）。每个槽各有自己的草稿、
	// 版本、发布指针与地址（见 docs/design/galaxy/site-model.md）。
	//
	// 名称**不参与任何查找**：不按名称查工程、不加唯一约束、不进发布地址。
	// 一旦名称成为查找键，它就成了一条可以被改名或抢注改写的路径。
	CreateProject(context.Context, *CreateProjectRequest) (*CreateProjectResponse, error)
	// 给一个已有工程加一个内容槽。
	//
	// **单向**：没有"删掉一个槽"的对应方法——槽的语义与地址是固定的，已有的版本
	// 与地址都挂在它上面，因此删除要单独论证（见 site-model.md）。**加一个槽不
	// 改变另一个槽**：那个槽的草稿、版本、发布指针与地址都原样。
	AddProjectSlot(context.Context, *AddProjectSlotRequest) (*AddProjectSlotResponse, error)
	// 读取一个工程的元数据。不含草稿清单、版本清单与资产字节。
	GetProject(context.Context, *GetProjectRequest) (*GetProjectResponse, error)
	// 修改工程的名称与简介。请求表达的是**期望的完整状态**，空串表示清空。
	//
	// **不含内容槽**：槽只增不删，且"有哪些槽"由 AddProjectSlot 回答，因此它不在
	// 这个请求的形状里。
	UpdateProject(context.Context, *UpdateProjectRequest) (*UpdateProjectResponse, error)
	// 删除一个工程。**连带删除它的全部版本、资产与发布记录**，因此已发布的
	// 地址立刻变成"不存在"。公开区上已上架的字节不回收（见发布一节）。
	DeleteProject(context.Context, *DeleteProjectRequest) (*DeleteProjectResponse, error)
	// 读取工程的当前草稿清单，每一项带一条短时读取地址。
	//
	// 草稿行是惰性创建的：从未推送过草稿时清单为空。地址由客户端直连取字节，
	// 服务端不代理（见 docs/design/galaxy/asset-library.md）。
	GetDraft(context.Context, *GetDraftRequest) (*GetDraftResponse, error)
	// 以给定的清单**整组替换**草稿（它不产生版本）。
	//
	// 它表达的是**期望的完整状态**，不是增量：清单里没有的路径就是"删掉"。
	// 否则"我到底删没删掉那一份"会变成一个需要读命令行实现才能回答的问题。
	//
	// **这是内容唯一的写入路径**（命令行）。网页端只读：两个入口并存会引出
	// "网页上刚改的一句被一次 push 静默盖掉"这类只在两个入口之间发生的冲突，
	// 收成一条路径，那份冲突连同它需要的基线校验一起不存在。
	//
	// 请求里的条目**只引用已经上传好的对象**（文本条目是内容摘要，资产条目是
	// 资产标识），因此本方法不带字节，也不触发任何上传。
	PushDraft(context.Context, *PushDraftRequest) (*PushDraftResponse, error)
	// 把草稿的当前清单保存成一个**不可变**版本。
	//
	// 保存即冻结：此后改草稿、改工程名称、删资产都不改变这个版本读回的内容。
	// 连续保存两次相同清单产生两个版本，而不是"检测到重复就不新增"——两份
	// 看起来一样的清单对用户是两次不同的保存动作。
	SaveVersion(context.Context, *SaveVersionRequest) (*SaveVersionResponse, error)
	// 列出工程的版本，按序号排序。清单很小，因此**列表也带清单**（不带地址）。
	ListVersions(context.Context, *ListVersionsRequest) (*ListVersionsResponse, error)
	// 读取一个版本，含清单与每一项的短时读取地址。保存时的内容此后逐字不变。
	GetVersion(context.Context, *GetVersionRequest) (*GetVersionResponse, error)
	// 删除一个版本。**被当前发布指向的版本不可删**——那会让发布地址指向一个
	// 不存在的版本。序号不因删除而重排，因此删中间一个会留下空洞。
	DeleteVersion(context.Context, *DeleteVersionRequest) (*DeleteVersionResponse, error)
	// 校验**当前草稿的清单**能不能发布。**编辑器提示与发布前置校验共用这一个
	// 入口。**
	//
	// 前端**不得**复写一套引用解析：两端各写一份的表现是"提示说没问题、发布
	// 说不行"（或反过来），而用户无法从任何一个提示里知道哪句是真的。它返回的
	// 是一个**问题清单**而不是单个错误——界面要的是"哪几处有问题"。
	// 存储不可用这类故障仍然以 RPC 错误返回，与"内容有问题"分开。
	//
	// 它校验的是**已保存的草稿**，请求里不带内容：写入只有一条路径（命令行
	// push 整组），因此"校验一份还没保存的内容"这个形状不存在。
	//
	// 它只读，但**不**标 idempotency_level：标了就等于同时接受 GET，而这条
	// 路径要读对象存储、可能较慢，不适合被当作可缓存的安全方法。
	ValidateDraft(context.Context, *ValidateDraftRequest) (*ValidateDraftResponse, error)
	// 给出**草稿整站的预览地址**，供只有本人能看的预览使用。
	//
	// 预览不是"把一份 HTML 塞进 iframe"：服务端把草稿整组按发布的路径形状，从
	// 发布域上一条带**短时凭证**的地址上提供（见 docs/design/galaxy/site-model.md
	// 的"预览"与 authoring.md）。页面因此有自己的源与目录，页内的相对地址、站点
	// 绝对地址与脚本里拼出来的路径都由浏览器自己解析——与发布态同一套道理。
	//
	// 凭证短时有效、随地址走；过期的表现是这一页取不到，重新调用本方法即得到新
	// 地址（与"重新读取档案即得到新地址"同源）。
	PreviewDraft(context.Context, *PreviewDraftRequest) (*PreviewDraftResponse, error)
	// 开始一次**内容对象**（文本条目）的上传：签发一份直传凭证。
	//
	// 内容对象与资产走**同一条直传链路**，差别只有三处：键按内容摘要、类型由
	// 路径与内容槽派生（不存在"声明"这一层）、不进公开区。
	//
	// **按内容摘要寻址对写入提了一条硬性约束：仅当对象不存在时才允许写入。**
	// 否则一个伪造的摘要会落到另一个版本已经在用的键上，把那个对象改写掉——
	// 而那是"版本不可变"的反面。凭证带"禁止覆盖"的写入条件，提交时服务端再
	// 读回核对一次摘要。
	BeginContentUpload(context.Context, *BeginContentUploadRequest) (*BeginContentUploadResponse, error)
	// 提交一次内容对象上传：读回对象、核对摘要。
	//
	// **摘要是寻址键，而服务端没有字节可以自己算它**——它由上传方声明。因此
	// 写入之后必须读回核对一遍，不一致即删除该对象并拒绝。
	CommitContentUpload(context.Context, *CommitContentUploadRequest) (*CommitContentUploadResponse, error)
	// 列出工程资产库里的资产，含**短时有效**的读取地址。
	//
	// 可选按标签筛选（精确匹配、多值取**交集**）。响应里另给一份**整个工程**
	// 已有的标签，供筛选界面做候选——它不随本次筛选收窄，否则筛一次之后候选
	// 就只剩下筛出来的那几个，用户无法取回原来的面。
	ListAssets(context.Context, *ListAssetsRequest) (*ListAssetsResponse, error)
	// 开始一次资产上传：分配资产标识并签发一份直传凭证。
	//
	// **字节不经过服务端**（见 docs/design/objectstore/README.md）。服务端在这里
	// 做三件事：校验调用的工程属于调用者、校验**声明的**内容类型在白名单内、
	// 按声明的大小早退；然后把"只许写这一个键、类型与大小受条件约束"的策略交给
	// 对象存储，由它执行。
	//
	// **类型与摘要都是上传方声明的，服务端不看字节。** 类型决定此后下发时回给
	// 浏览器的内容类型，而白名单里没有任何可执行类型——因此公开区上的对象永远
	// 以一个无害类型下发；摘要则在提交时被核对（让存储侧算，存储侧给不出时读回
	// 自己算），不一致即拒绝提交。
	BeginAssetUpload(context.Context, *BeginAssetUploadRequest) (*BeginAssetUploadResponse, error)
	// 提交一次资产上传：核对字节确实到了、内容与声明的摘要相符，写入资产元数据。
	//
	// 签发之后客户端传了什么、传没传完，服务端都不知道，因此提交要对那个键做
	// 一次 Head：不存在即失败，字节数超过上限即失败并删除对象；随后核对摘要，
	// 不符同样删除对象并拒绝。**没有提交的上传不会进入任何清单**（元数据行不存在）。
	//
	// 可以顺带带上初始的标题 / 标签 / 备注（都可空）。一次带走省掉一次往返，
	// 而结果与"提交之后再调 UpdateAsset"完全相同。
	CommitAssetUpload(context.Context, *CommitAssetUploadRequest) (*CommitAssetUploadResponse, error)
	// 删除一个资产。**被任一版本的文件清单引用时拒绝**，错误信息指出被哪些
	// 版本引用。
	//
	// 拒绝的理由是版本不可变的含义包括"它此后永远可以发布"：一个引用了已删
	// 除资产的版本必然在校验阶段失败，而那时用户看到一句"资产不存在"，却无法
	// 从版本内容里知道该怎么做。把问题挡在它产生的地方。
	DeleteAsset(context.Context, *DeleteAssetRequest) (*DeleteAssetResponse, error)
	// 改一个资产的展示标题、标签与备注。
	//
	// **它只改"说明层"。** 资产有不可变与可变两层（见
	// docs/design/galaxy/asset-library.md）：字节、内容摘要、媒体类型、类别与
	// 字节数在改动前后逐字不变，因此公开区地址不变、已发布页面拿到的还是同一
	// 份字节。接口面上不存在"替换资产字节"的方法。
	//
	// 请求表达**期望的完整状态**（与 UpdateProject 同取向）：空串清空标题或
	// 备注，标签以请求集合**整体替换**。
	UpdateAsset(context.Context, *UpdateAssetRequest) (*UpdateAssetResponse, error)
	// 发布一个版本：校验、把引用的资产上架到公开区、落库产物清单、切换发布指针。
	//
	// **只能发布版本，不能发布草稿**——草稿是可变的，"发布一个可变的东西"
	// 没有意义。草稿清单不会被读取。
	//
	// 发布域未配置时这一项不可用（见 GetCapabilities）。
	Publish(context.Context, *PublishRequest) (*PublishResponse, error)
	// 撤回发布：把发布指针置空，地址立刻不可达。
	//
	// 发布记录保留，因此可以重新发布同一个版本；公开区的副本不因撤回而删除。
	// 撤回用发布那一码——它是发布的反向操作，不给它单独一码不会带来任何安全
	// 收益，只会让"发布得出去、收不回来"变成一个可以只授一半的组合。
	Unpublish(context.Context, *UnpublishRequest) (*UnpublishResponse, error)
	// 读回**某个槽当前发布**的那一份产物清单：发布记录、路径、以及每一项在**访客
	// 路径**上的读取地址。
	//
	// 它是"发布成功了"这件事的核对入口。发布物里的地址是渲染时补上的（源里、版本
	// 里都只有 `asset://` 记号），因此只拿着 Publish 的返回值证明不了引用都解开了。
	// 清单就是发布时落库的那一条记录——**不是重新算一遍**，因此它回答的正是"现在
	// 发出去的是什么"。
	//
	// **未发布不是错误**：那时 publication 与 entries 都为空，与 published_url
	// 为空是同一条取向。
	//
	// 它是**归属内的读**（发布者核对自己的产物），因此要 `galaxy.project.read` 与
	// 工程归属；发布态本身仍是公开匿名的，那是发布域那条 HTTP 入口的事。
	GetPublication(context.Context, *GetPublicationRequest) (*GetPublicationResponse, error)
	// 把一条**主站分享路径**解析成它在发布域上的内容地址。
	//
	// 主站壳（`<主站>/g/<工程标识>[/docs][/路径]`）用它问出 iframe 该指向哪里。
	// **槽的判定在服务端**（与发布地址那条 HTTP 入口共用同一处形状解析），因此
	// 请求给的是整条路径，响应给的是整条内容地址——客户端两头都不拼。
	//
	// 它是**公开**的：访客打开一条分享地址时没有会话，而"分享给没登录的人"正是
	// 这个入口唯一的用途（见 docs/design/rbac/server-permissions.md 的公开方法白
	// 名单）。它只凭工程标识作答，与发布地址那条 HTTP 入口回答的是同一件事。
	//
	// **否定结论只有一个**：未发布、已撤回、该槽未启用、工程不存在、标识没被猜
	// 中、路径不在集合里，一律返回空的 `content_url`，而不是 RPC 错误——错误码会
	// 成为一个"这个标识是真的"的第二信号（见 docs/design/galaxy/publication.md 的
	// "主站壳"）。
	ResolveSharedPage(context.Context, *ResolveSharedPageRequest) (*ResolveSharedPageResponse, error)
	mustEmbedUnimplementedGalaxyServiceServer()
}

